using System;using System.Drawing;using System.Windows.Forms;
internal static class VeilColors{public static Color Canvas,Ink,Button,OnButton;static VeilColors(){Set("light");}public static void Set(string theme){bool light=theme=="light";Canvas=light?Color.FromArgb(244,242,252):theme=="gray"?Color.FromArgb(36,35,47):Color.FromArgb(13,12,16);Ink=light?Color.FromArgb(41,39,56):Color.FromArgb(242,238,248);Button=light?Color.FromArgb(41,38,63):Color.FromArgb(187,155,245);OnButton=light?Color.White:Color.FromArgb(33,21,46);}}
internal static class VeilMessage{public static Action<string> Notify;public static DialogResult Show(string body,string title){return Show(null,body,title);}public static DialogResult Show(IWin32Window owner,string body,string title="CapCut Launcher",MessageBoxButtons buttons=MessageBoxButtons.OK,MessageBoxIcon icon=MessageBoxIcon.None){if(Notify!=null&&buttons==MessageBoxButtons.OK){Notify(body);return DialogResult.OK;}return MessageBox.Show(owner,body,title,buttons,icon);}}
